import{_ as t,c as i,o as r,ae as o}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"INCREASING EFFICIENCY AT THE OFFICE OF THE FEDERAL REGISTER","description":"","frontmatter":{"title":"INCREASING EFFICIENCY AT THE OFFICE OF THE FEDERAL REGISTER","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/05/increasing-efficiency-at-the-office-of-the-federal-register/","publishDate":"2025-05-09T18:11:35-04:00"},"headers":[],"relativePath":"executive-orders/2025-05-09-increasing-efficiency-at-the-office-of-the-federal-register.md","filePath":"executive-orders/2025-05-09-increasing-efficiency-at-the-office-of-the-federal-register.md"}'),s={name:"executive-orders/2025-05-09-increasing-efficiency-at-the-office-of-the-federal-register.md"};function n(a,e,c,l,f,d){return r(),i("div",null,e[0]||(e[0]=[o('<h1 id="increasing-efficiency-at-the-office-of-the-federal-register" tabindex="-1">INCREASING EFFICIENCY AT THE OFFICE OF THE FEDERAL REGISTER <a class="header-anchor" href="#increasing-efficiency-at-the-office-of-the-federal-register" aria-label="Permalink to &quot;INCREASING EFFICIENCY AT THE OFFICE OF THE FEDERAL REGISTER&quot;">​</a></h1><p>Published: Friday, May 9, 2025</p><ul><li>The Administration prioritizes deregulation to ease the burden of Federal regulations on Americans.</li><li>Current delays in publishing regulatory actions by the Office of the Federal Register are criticized as unnecessary and costly.</li><li>Executive departments and agencies incur high costs for publishing rules, which undermines the deregulatory agenda.</li></ul><p><strong>Actions Ordered:</strong></p><ul><li><p><strong>Modernization and Efficiency:</strong></p><ul><li>The Archivist of the United States is tasked with collaborating with the Government Publishing Office to reduce publication delays, including modernization of computer systems and streamlining processes.</li></ul></li><li><p><strong>Reporting Requirements:</strong></p><ul><li><strong>15 Days Post-Order:</strong> The Archivist must report average publication times for various documents to the Director of the Office of Management and Budget (OMB).</li><li><strong>45 Days Post-Order:</strong> A review of publication fee schedules must be conducted to ensure costs reflect actual publication expenses and any efficiencies gained. A report comparing new and prior fee schedules must be submitted to the Director of OMB.</li><li><strong>By August 22, 2025:</strong> A second report detailing average publication times for specific document categories must be submitted to the Director of OMB.</li></ul></li></ul><p><strong>Legal Provisions:</strong></p><ul><li>The order does not affect the statutory authority of executive departments or the functions of the OMB.</li><li>Implementation must comply with applicable law and available funding.</li><li>The order does not create enforceable rights against the U.S. or its entities.</li><li>Publication costs for this order will be covered by the National Archives and Records Administration.</li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/05/increasing-efficiency-at-the-office-of-the-federal-register/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/05/increasing-efficiency-at-the-office-of-the-federal-register/</a></p>',8)]))}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
